.ka-calendar-summary span{font-size:.76rem;color:var(--ka-text-muted);font-weight:700}
.ka-calendar-weekdays,.ka-calendar-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:5px}
.ka-calendar-weekdays{padding:2px 1px}
