/* Koruk Asistan — zil sayacı modern durum kartı */
@media (max-width:1023px){
  .ka-home{padding-left:max(12px,var(--ka-safe-left))!important;padding-right:max(12px,var(--ka-safe-right))!important;gap:20px!important}.ka-home .kh-section{gap:12px}
  .ka-home .kh-shell{width:100%!important;max-width:none!important;margin-left:auto!important;margin-right:auto!important}
  .ka-home .kh-section,.ka-home .kh-dynamic,.ka-home .kh-news,.ka-home .kh-stats,.ka-home .kh-social,.ka-home .kh-quick,.ka-home .kh-hero{width:100%!important;max-width:none!important}
