  .ka-home #khBell{order:1}
  .ka-home #khWeather{order:2}
}
#khBell:not(.kh-bell-modern){opacity:0!important;pointer-events:none!important}
#khBell.kh-bell-modern{
  --kb-accent:#c99700;--kb-accent-2:#ffc400;--kb-soft:#fff7d6;--kb-text:#24200f;--kb-muted:#756f5b;--kb-line:#eadba0;--kb-track:#e8e0bf;
  --kb-lesson:#c99700;--kb-break:#b76500;--kb-lunch:#7e56b5;
  display:block!important;position:relative;overflow:hidden;min-height:0!important;padding:0!important;border-radius:22px!important;
  background:linear-gradient(145deg,#fffdf3,#f8f4e4)!important;border:1px solid var(--kb-line)!important;
  color:var(--kb-text)!important;box-shadow:0 9px 26px rgba(110,84,0,.10)!important;text-align:left!important;opacity:1!important;
}
[data-theme="dark"] #khBell.kh-bell-modern{
  --kb-accent:#ffc400;--kb-accent-2:#ffe071;--kb-soft:#3a300c;--kb-text:#f7f3df;--kb-muted:#aaa38b;--kb-line:#55491f;--kb-track:#383421;
  --kb-lesson:#ffc400;--kb-break:#ffbd62;--kb-lunch:#c79cff;
  background:linear-gradient(145deg,#171717,#101010)!important;box-shadow:0 12px 28px rgba(0,0,0,.32)!important
}
#khBell.kh-bell-modern:active{transform:none!important}
.kh-bell-wrap{padding:14px 14px 15px}
