.kh-bell-title{min-width:0}.kh-bell-title strong{display:block;font-size:17px;font-weight:900;line-height:1.15;color:var(--kb-text);letter-spacing:-.01em}.kh-bell-title span{display:block;margin-top:3px;font-size:10px;font-weight:800;color:var(--kb-accent)}
