.kh-bell-progress{position:relative;height:10px;margin:12px 1px 0;border-radius:999px;background:var(--kb-track);overflow:hidden;box-shadow:inset 0 1px 2px rgba(0,0,0,.08)}
.kh-bell-progress>i{display:block;height:100%;width:var(--kb-progress,0%);border-radius:inherit;background:linear-gradient(90deg,var(--kb-accent),var(--kb-accent-2));position:relative;overflow:hidden;z-index:1;transition:width .8s cubic-bezier(.2,.8,.2,1)}
.kh-bell-progress>i:after{content:"";position:absolute;inset:0;background:repeating-linear-gradient(120deg,transparent 0 9px,rgba(255,255,255,.19) 9px 15px);background-size:24px 100%;animation:khBellFlow 1.25s linear infinite}
