  border-radius:999px;background:var(--ka-text-muted);transform:rotate(45deg);transform-origin:left center;pointer-events:none
}
.ka-communication-page:has(.ka-notes-workspace)>.ka-communication-search input:focus{
  border-color:var(--ka-primary);box-shadow:0 0 0 3px var(--ka-focus),var(--ka-shadow-sm)
}

.ka-notes-workspace{gap:14px;padding-bottom:6px}
.ka-notes-hero{
  position:relative;isolation:isolate;overflow:hidden;min-height:146px;padding:22px;
  align-items:flex-end;border-color:var(--ka-hero-border);border-radius:24px;background:var(--ka-hero-bg);
  box-shadow:var(--ka-hero-shadow)
}
.ka-notes-hero::after{
  content:"";position:absolute;z-index:-1;right:-72px;top:-92px;width:190px;height:190px;border-radius:50%;
  background:color-mix(in srgb,var(--ka-primary) 10%,transparent)
}
.ka-notes-hero>div{max-width:560px}
.ka-notes-kicker{font-size:11px;letter-spacing:.14em;color:var(--ka-hero-kicker)}
.ka-notes-hero h1{margin-top:5px;font-size:clamp(30px,7vw,38px);letter-spacing:-.035em;color:var(--ka-hero-text)}
.ka-notes-hero p{max-width:520px;margin-top:7px;font-size:14px;line-height:1.5;color:var(--ka-hero-muted)}
.ka-notes-hero .ka-btn{
  position:relative;z-index:1;min-width:154px;min-height:48px;border-radius:15px;
  background:var(--ka-button-bg);color:var(--ka-button-text);box-shadow:0 8px 20px color-mix(in srgb,var(--ka-primary) 18%,transparent)
}

.ka-notes-summary{gap:9px}
.ka-notes-summary article{
  min-height:86px;padding:12px 13px;border-color:var(--ka-border);border-radius:18px;
  background:var(--ka-card-bg);color:var(--ka-text);box-shadow:var(--ka-shadow-sm)
}
.ka-notes-summary article>span{
  width:40px;height:40px;border-radius:13px;background:var(--ka-primary-soft);font-size:19px
}
.ka-notes-summary article:nth-child(2)>span{background:color-mix(in srgb,var(--ka-warning) 13%,var(--ka-card-bg))}
.ka-notes-summary article:nth-child(3)>span{background:color-mix(in srgb,var(--ka-accent) 13%,var(--ka-card-bg))}
.ka-notes-summary small{font-size:11px;line-height:1.25;color:var(--ka-text-muted);font-weight:800}
.ka-notes-summary b{margin-top:3px;font-size:25px;color:var(--ka-text);letter-spacing:-.03em}
.ka-notes-group{gap:10px}
.ka-notes-group__head{padding:3px 2px}
.ka-notes-group__head h3{font-size:16px;letter-spacing:-.01em}
.ka-notes-group__head .ka-badge{background:var(--ka-primary-soft);color:var(--ka-primary)}
.ka-notes-grid{gap:12px}

.ka-note-card{
  position:relative;border:1px solid color-mix(in srgb,var(--note-accent) 26%,var(--ka-border));
  border-left-width:1px;border-radius:20px;
  background:linear-gradient(180deg,color-mix(in srgb,var(--note-accent) 5%,var(--ka-card-bg)) 0,var(--ka-card-bg) 66px);
  color:var(--ka-text);box-shadow:var(--ka-shadow-sm)
}
.ka-note-card::before{content:"";display:block;flex:0 0 4px;height:4px;background:var(--note-accent)}
.ka-note-card:hover{border-color:color-mix(in srgb,var(--note-accent) 38%,var(--ka-border-strong));box-shadow:var(--ka-shadow-md)}
.ka-note-card__open{min-height:0;gap:12px;padding:15px 16px 14px}
.ka-note-card__head{gap:10px}
.ka-note-card__head>strong{font-size:16px;line-height:1.25;color:var(--ka-text);font-weight:850}
.ka-note-type span{
  width:34px;height:34px;border:1px solid color-mix(in srgb,var(--note-accent) 22%,var(--ka-border));
  border-radius:11px;background:color-mix(in srgb,var(--note-accent) 10%,var(--ka-card-bg));font-size:16px
}
.ka-note-card__date{
  padding:4px 7px;border:1px solid var(--ka-border);border-radius:999px;background:var(--ka-muted-bg);
  color:var(--ka-text-muted);font-size:10px
}
.ka-note-card__preview{font-size:13px;line-height:1.55;color:var(--ka-text)}
.ka-note-rich-preview{max-height:126px;color:var(--ka-text)}
.ka-note-todo-preview{gap:7px}
.ka-note-todo-row{gap:9px}
.ka-note-tags{gap:6px}
.ka-note-tags span{
  padding:4px 8px;background:color-mix(in srgb,var(--note-accent,var(--ka-primary)) 8%,var(--ka-card-bg));
  border-color:color-mix(in srgb,var(--note-accent,var(--ka-primary)) 22%,var(--ka-border));
  color:var(--ka-text-muted);font-size:10px
}
.ka-note-owner,.ka-note-progress{font-size:11px;color:var(--ka-text-muted)}
.ka-note-card__actions{
  display:grid;grid-template-columns:minmax(0,1fr) minmax(76px,.48fr);gap:8px;padding:10px 12px 12px;
  border-top:1px solid var(--ka-border);background:color-mix(in srgb,var(--ka-card-bg) 96%,var(--note-accent) 4%)
}
.ka-note-card__actions .ka-btn{min-height:40px;border-radius:12px;font-size:13px}
.ka-note-card__actions .ka-btn--secondary{
  border-color:color-mix(in srgb,var(--ka-primary) 22%,var(--ka-border));background:var(--ka-primary-soft);color:var(--ka-primary)
}
.ka-note-card__actions .ka-btn--ghost{
  border-color:color-mix(in srgb,var(--ka-danger) 18%,var(--ka-border));
  background:color-mix(in srgb,var(--ka-danger) 8%,var(--ka-card-bg));color:var(--ka-danger)
}
.ka-note-color{
  background:color-mix(in srgb,var(--note-accent) 28%,var(--ka-card-bg));
  border-color:var(--ka-card-bg)
}
.ka-note-color.active{box-shadow:0 0 0 3px var(--ka-card-bg),0 0 0 5px var(--note-accent)}

[data-theme="dark"] .ka-note-card{
  border-color:color-mix(in srgb,var(--note-accent) 32%,var(--ka-border));
  background:linear-gradient(180deg,color-mix(in srgb,var(--note-accent) 8%,var(--ka-card-bg)) 0,var(--ka-card-bg) 72px)
}
[data-theme="dark"] .ka-note-card__date{background:color-mix(in srgb,var(--ka-muted-bg) 88%,transparent)}
[data-theme="dark"] .ka-note-card__actions{background:color-mix(in srgb,var(--ka-card-bg) 94%,var(--note-accent) 6%)}
[data-theme="dark"] .ka-note-color{background:color-mix(in srgb,var(--note-accent) 38%,var(--ka-card-bg))}
[data-theme="dark"] .ka-notes-summary article{background:var(--ka-card-bg)}
[data-theme="dark"] .ka-notes-hero .ka-btn{box-shadow:none}

@media(max-width:640px){
  .ka-communication-page:has(.ka-notes-workspace){gap:12px}
  .ka-communication-page:has(.ka-notes-workspace)>.ka-communication-search input{min-height:50px;border-radius:16px}
  .ka-notes-workspace{gap:12px}
  .ka-notes-hero{min-height:0;padding:18px;border-radius:21px}
  .ka-notes-hero h1{font-size:30px}
  .ka-notes-hero p{font-size:13px}
  .ka-notes-hero .ka-btn{width:100%;min-height:46px;margin-top:2px}
  .ka-notes-summary{gap:7px}
  .ka-notes-summary article{min-height:78px;gap:8px;padding:10px 9px;border-radius:16px}
  .ka-notes-summary article>span{width:36px;height:36px;border-radius:11px;font-size:17px}
  .ka-notes-summary small{font-size:10px}
  .ka-notes-summary b{font-size:22px}
  .ka-notes-grid{gap:11px}
  .ka-note-card{border-radius:18px}
  .ka-note-card__open{padding:14px}
  .ka-note-card__head>strong{font-size:15px}
  .ka-note-card__preview{font-size:13px}
  .ka-note-card__actions{padding:9px 10px 10px}
}
@media(max-width:370px){
  .ka-notes-summary article{display:grid;justify-items:center;text-align:center;gap:5px;padding:9px 5px}
  .ka-notes-summary article>span{width:32px;height:32px}
  .ka-notes-summary small{font-size:9.5px}
  .ka-notes-summary b{font-size:21px}
}

/* ===== RUBRIC / EXAM WORKSPACE REDESIGN 2026-09-05 ===== */
/* Görsel katman: davranış, DOM ve local-first veri akışı değiştirilmez. */
.ka-rubric-workspace{
  width:min(1080px,100%);
  height:min(94dvh,880px);
  border-color:color-mix(in srgb,var(--ka-primary) 16%,var(--ka-border));
  border-radius:24px;
  background:color-mix(in srgb,var(--ka-app-bg) 94%,var(--ka-card-bg));
}
.ka-rubric-workspace__header{
  gap:12px;
  padding:12px 14px;
  background:linear-gradient(135deg,color-mix(in srgb,var(--ka-primary) 92%,#fff),var(--ka-primary));
  box-shadow:0 8px 24px color-mix(in srgb,var(--ka-primary) 20%,transparent);
}
.ka-rubric-workspace__identity{gap:10px}
.ka-rubric-workspace__icon{
  width:40px;height:40px;flex-basis:40px;border-radius:13px;
  background:color-mix(in srgb,#fff 18%,transparent);
  border:1px solid color-mix(in srgb,#fff 22%,transparent);
  font-size:20px;
}
.ka-rubric-workspace__identity h2{
  font-size:18px;line-height:1.12;letter-spacing:-.015em;font-weight:850;
}
.ka-rubric-workspace__identity p{margin-top:2px;font-size:10.5px}
.ka-rubric-workspace__actions{gap:6px;flex-wrap:nowrap}
.ka-rubric-workspace__actions .ka-btn{
  min-height:38px;padding:7px 11px;border-radius:12px;font-size:11px;font-weight:800;white-space:nowrap;
}
.ka-rubric-workspace__actions .ka-btn--secondary{
  background:color-mix(in srgb,#fff 14%,transparent);
  border-color:color-mix(in srgb,#fff 28%,transparent);
  color:#fff;
}
.ka-rubric-workspace__actions .ka-btn--secondary:hover{
  background:color-mix(in srgb,#fff 22%,transparent);color:#fff;
}
.ka-rubric-workspace__body{
  padding:14px;
  background:
    radial-gradient(circle at 12% -10%,color-mix(in srgb,var(--ka-primary) 8%,transparent),transparent 34%),
    var(--ka-app-bg);
}
.ka-rubric-flow{width:min(940px,100%)}
.ka-rubric-step{
  overflow:hidden;
  border:1px solid color-mix(in srgb,var(--ka-primary) 14%,var(--ka-border));
  border-radius:20px;
  background:var(--ka-card-bg);
  box-shadow:0 12px 30px color-mix(in srgb,#000 7%,transparent);
}
.ka-rubric-step__head{
  gap:11px;padding:12px 14px;
  background:linear-gradient(90deg,color-mix(in srgb,var(--ka-primary-soft) 76%,var(--ka-card-bg)),var(--ka-card-bg));
  border-bottom:1px solid var(--ka-border);
}
.ka-rubric-step__head>span{
  min-width:46px;height:32px;padding:0 9px;border-radius:999px;
  background:var(--ka-primary);color:var(--ka-button-text);
  box-shadow:0 5px 14px color-mix(in srgb,var(--ka-primary) 20%,transparent);
  font-size:11px;font-weight:900;
}
.ka-rubric-step__head h3{font-size:16px;line-height:1.15;letter-spacing:-.01em}
.ka-rubric-step__head p{margin-top:2px;font-size:10.5px;line-height:1.35}
.ka-rubric-step__body{padding:14px;gap:12px}
.ka-rubric-step__body>.ka-grid{gap:11px 12px}
.ka-rubric-step .ka-field{gap:5px}
.ka-rubric-step .ka-field__label{font-size:11.5px;font-weight:800;color:var(--ka-text)}
.ka-rubric-step input:not([type="file"]),
.ka-rubric-step select{
  min-height:46px;height:46px;padding:9px 11px;border-radius:13px;
  background:color-mix(in srgb,var(--ka-card-bg) 94%,var(--ka-muted-bg));
  font-size:12.5px;
}
.ka-rubric-step input[type="file"]{
  min-height:48px;padding:9px;border:1px dashed color-mix(in srgb,var(--ka-primary) 35%,var(--ka-border));
  border-radius:13px;background:var(--ka-primary-soft);
}
.ka-rubric-step__body>.ka-btn:last-child{min-height:46px;border-radius:13px;font-weight:850}
.ka-rubric-choice-grid{gap:8px}
.ka-rubric-preview{border-radius:14px;border-color:var(--ka-border);background:#fff}

/* Ölçüt düzenleyici: daha kısa, daha okunaklı, mobilde taşmayan düzen. */
.ka-rubric-settings{
  width:min(860px,calc(100% - 24px));
  max-height:min(92dvh,820px);
  border-radius:22px;
  border:1px solid color-mix(in srgb,var(--ka-primary) 18%,var(--ka-border));
  background:var(--ka-card-bg);
  box-shadow:0 24px 70px color-mix(in srgb,#000 30%,transparent);
}
.ka-rubric-settings__header{
  align-items:center;padding:13px 15px;
  background:linear-gradient(135deg,color-mix(in srgb,var(--ka-primary-soft) 86%,var(--ka-card-bg)),var(--ka-card-bg));
  border-bottom:1px solid var(--ka-border);
}
.ka-rubric-settings__header h3{font-size:18px;line-height:1.15;letter-spacing:-.01em}
.ka-rubric-settings__header p{margin-top:3px;font-size:10.5px;line-height:1.35}
.ka-rubric-settings__header #rtx{
  min-height:38px;padding:7px 11px;border-radius:12px;white-space:nowrap;
}
.ka-rubric-settings .ka-modal__body{
  gap:12px;padding:13px 15px 16px;
  background:color-mix(in srgb,var(--ka-app-bg) 76%,var(--ka-card-bg));
  scrollbar-gutter:stable;
}
.ka-rubric-settings .ka-field{gap:5px;min-width:0}
.ka-rubric-settings .ka-field__label{font-size:11px;font-weight:800;color:var(--ka-text)}
.ka-rubric-settings input,
.ka-rubric-settings select{
  min-width:0;width:100%;min-height:44px;height:44px;
  padding:8px 10px;border-radius:12px;
  background:var(--ka-card-bg);font-size:12px;
}
.ka-rubric-settings #rtform{min-width:0}
.ka-rubric-settings #rtform>.ka-grid{
  grid-template-columns:repeat(2,minmax(0,1fr));gap:9px;
}
.ka-rubric-settings #rtform>.ka-stack{gap:11px}
.ka-rubric-settings #rtlabels{
  display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px 9px;
}
.ka-rubric-settings #rtlabels .ka-field{
  display:grid;grid-template-columns:28px minmax(0,1fr);align-items:center;gap:7px;
}
.ka-rubric-settings #rtlabels .ka-field__label{
  display:grid;place-items:center;margin:0;min-height:28px;border-radius:8px;
  background:var(--ka-primary-soft);color:var(--ka-primary);font-size:10.5px;font-weight:900;
}
.ka-rubric-settings #rtlabels input{height:40px;min-height:40px}
.ka-rubric-settings #rtgroups{gap:10px}
.ka-rubric-settings #rtgroups>.ka-card{
  overflow:hidden;border-radius:16px;
  border:1px solid color-mix(in srgb,var(--ka-primary) 12%,var(--ka-border));
  background:var(--ka-card-bg);box-shadow:none;
}
.ka-rubric-settings #rtgroups>.ka-card .ka-card__body{gap:8px;padding:11px}
.ka-rubric-settings #rtgroups>.ka-card .ka-field{margin-bottom:1px}
.ka-rubric-settings #rtgroups>.ka-card .ka-field__label{
  font-size:10.5px;text-transform:uppercase;letter-spacing:.035em;color:var(--ka-text-muted);
}
.ka-rubric-settings #rtgroups>.ka-card .ka-row:has(>[data-del-k]){
  display:grid;grid-template-columns:minmax(0,1fr) 52px;align-items:stretch;gap:7px;
}
.ka-rubric-settings #rtgroups input[id^="rtk"]{
  width:100%;min-width:0;height:42px;min-height:42px;
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
}
.ka-rubric-settings [data-del-k]{
  width:52px;min-width:52px;min-height:42px;padding:6px;border-radius:11px;
  background:color-mix(in srgb,var(--ka-danger) 10%,var(--ka-card-bg));
  border-color:color-mix(in srgb,var(--ka-danger) 28%,var(--ka-border));
  color:var(--ka-danger);font-size:10.5px;font-weight:850;
}
.ka-rubric-settings [data-del-k]:hover{
  background:color-mix(in srgb,var(--ka-danger) 16%,var(--ka-card-bg));color:var(--ka-danger);
}
.ka-rubric-settings #rtgroups>.ka-card .ka-row:has(>[data-add-k]){
  display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:7px;margin-top:2px;
}
.ka-rubric-settings [data-add-k],
.ka-rubric-settings [data-del-g]{
  width:100%;min-height:40px;padding:7px 9px;border-radius:11px;font-size:10.5px;font-weight:850;
}
.ka-rubric-settings [data-add-k]{
  background:var(--ka-primary);border-color:var(--ka-primary);color:var(--ka-button-text);
}
.ka-rubric-settings [data-del-g]{
  background:color-mix(in srgb,var(--ka-danger) 8%,var(--ka-card-bg));
  border-color:color-mix(in srgb,var(--ka-danger) 24%,var(--ka-border));color:var(--ka-danger);
}
.ka-rubric-settings #rtaddg{
  min-height:38px;padding:7px 11px;border-radius:11px;
  background:var(--ka-primary-soft);border-color:color-mix(in srgb,var(--ka-primary) 28%,var(--ka-border));
  color:var(--ka-primary);font-weight:850;
}
.ka-rubric-settings__footer{
  display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px;
  padding:10px 14px max(10px,var(--ka-safe-bottom));
  border-top:1px solid var(--ka-border);background:var(--ka-card-bg);
}
.ka-rubric-settings__footer .ka-btn{
  width:100%;min-height:42px;padding:8px 10px;border-radius:12px;
  font-size:10.5px;line-height:1.2;font-weight:850;
}
.ka-rubric-settings__footer #rtdeletecustom{grid-column:1/-1;margin:0;color:var(--ka-danger)}
.ka-rubric-settings__footer #rtsave{grid-column:1/-1;min-height:44px}
.ka-rubric-settings__footer:not(:has(#rtschool)) #rtcloud{grid-column:1/-1}

/* Sınavlar ve Not İşlemleri: yalnız rubric rotasını içeren menü grubu. */
.ka-menu-page:has([data-ka-shell-page="rubric"]){
  background:
    radial-gradient(circle at 50% -12%,color-mix(in srgb,var(--ka-primary) 10%,transparent),transparent 28%),
    var(--ka-app-bg);
}
.ka-menu-page:has([data-ka-shell-page="rubric"]) .ka-menu-head{
  min-height:68px;padding:10px 14px;
  border-bottom:1px solid var(--ka-border);
  background:color-mix(in srgb,var(--ka-app-bg) 92%,var(--ka-card-bg));
  backdrop-filter:blur(16px);
}
.ka-menu-page:has([data-ka-shell-page="rubric"]) .ka-menu-head h2{
  font-size:19px;line-height:1.15;letter-spacing:-.015em;font-weight:850;
}
.ka-menu-page:has([data-ka-shell-page="rubric"]) .ka-menu-head .ka-icon-button{
  width:38px;height:38px;border-radius:12px;
}
.ka-menu-page:has([data-ka-shell-page="rubric"]) .ka-menu-list{
  width:min(720px,100%);margin:0 auto;padding:14px 12px calc(100px + var(--ka-safe-bottom));gap:9px;
}
.ka-menu-page:has([data-ka-shell-page="rubric"]) .ka-menu-list>.ka-btn{
  min-height:62px;padding:8px 10px;border-radius:17px;
  border:1px solid color-mix(in srgb,var(--ka-primary) 12%,var(--ka-border));
  background:color-mix(in srgb,var(--ka-card-bg) 96%,var(--ka-primary-soft));
  box-shadow:0 7px 20px color-mix(in srgb,#000 5%,transparent);
  transition:transform .16s ease,border-color .16s ease,background .16s ease;
}
.ka-menu-page:has([data-ka-shell-page="rubric"]) .ka-menu-list>.ka-btn:hover{
  border-color:color-mix(in srgb,var(--ka-primary) 32%,var(--ka-border));
  background:color-mix(in srgb,var(--ka-primary-soft) 50%,var(--ka-card-bg));
}
.ka-menu-page:has([data-ka-shell-page="rubric"]) .ka-menu-list>.ka-btn:active{transform:scale(.985)}
.ka-menu-page:has([data-ka-shell-page="rubric"]) .ka-menu-list>.ka-btn .ka-avatar{
  width:42px;height:42px;flex:0 0 42px;border-radius:13px;
  background:var(--ka-primary-soft);border:1px solid color-mix(in srgb,var(--ka-primary) 14%,transparent);
  font-size:19px;
}
.ka-menu-page:has([data-ka-shell-page="rubric"]) .ka-menu-list>.ka-btn strong{
  font-size:13.5px;line-height:1.2;letter-spacing:-.005em;
}
.ka-menu-page:has([data-ka-shell-page="rubric"]) .ka-menu-list>.ka-btn>span:last-child{
  width:30px;height:30px;border-radius:10px;background:var(--ka-muted-bg);
}
.ka-menu-page:has([data-ka-shell-page="rubric"]) .ka-menu-list>.ka-btn[data-ka-shell-page="rubric"],
.ka-menu-page:has([data-ka-shell-page="rubric"]) .ka-menu-list>.ka-btn[data-ka-shell-page="project"]{
  border-color:color-mix(in srgb,var(--ka-primary) 26%,var(--ka-border));
  background:linear-gradient(90deg,color-mix(in srgb,var(--ka-primary-soft) 58%,var(--ka-card-bg)),var(--ka-card-bg) 72%);
}
.ka-menu-page:has([data-ka-shell-page="rubric"]) .ka-menu-list>.ka-btn[data-ka-shell-page="rubric"]::before,
.ka-menu-page:has([data-ka-shell-page="rubric"]) .ka-menu-list>.ka-btn[data-ka-shell-page="project"]::before{
  content:"";width:3px;align-self:stretch;border-radius:999px;background:var(--ka-primary);margin-right:1px;
}

