/* KORUK ASİSTAN — premium neutral surfaces / yellow-mint theme */
.ka-card,.card{transition:background var(--ka-transition-fast),border-color var(--ka-transition-fast),box-shadow var(--ka-transition-fast),transform var(--ka-transition-fast)}
.ka-card__header,.ka-card__body,.ka-card__footer{background:transparent}
.ka-list-card:hover{transform:translateY(-1px)}
.ka-btn,.btn{letter-spacing:-.01em}
.ka-btn:not(.ka-btn--secondary):not(.ka-btn--ghost):not(.ka-btn--danger),.btn:not(.ka-btn--secondary):not(.ka-btn--ghost):not(.ka-btn--danger){box-shadow:0 5px 14px color-mix(in srgb,var(--ka-primary) 16%,transparent)}
.ka-btn--secondary{box-shadow:none}
.ka-tab{transition:background var(--ka-transition-fast),color var(--ka-transition-fast),border-color var(--ka-transition-fast)}
.ka-tab.active,.ka-tab[aria-selected="true"]{border-color:color-mix(in srgb,var(--ka-primary) 42%,var(--ka-border))}
.ka-avatar{border:1px solid color-mix(in srgb,var(--ka-primary) 20%,var(--ka-border))}
.ka-table th{color:var(--ka-text);background:var(--ka-muted-bg)}
.ka-table tbody tr:hover td{background:color-mix(in srgb,var(--ka-primary) 5%,var(--ka-card-bg))}
[data-theme="dark"] .ka-table tbody tr:hover td{background:color-mix(in srgb,var(--ka-primary) 7%,var(--ka-card-bg))}
[data-theme="dark"] .ka-btn:not(.ka-btn--secondary):not(.ka-btn--ghost):not(.ka-btn--danger),
[data-theme="dark"] .btn:not(.ka-btn--secondary):not(.ka-btn--ghost):not(.ka-btn--danger){box-shadow:0 6px 18px rgba(0,0,0,.34)}
[data-theme="dark"] .ka-card,.ka-card{backdrop-filter:saturate(105%);-webkit-backdrop-filter:saturate(105%)}
@media (max-width:640px){
  .ka-card{border-radius:16px}
  .ka-card__header,.ka-card__body,.ka-card__footer{padding:14px}
  .ka-btn,.btn{min-height:42px}
}

/* Menu: readable text on saturated module surfaces */
.ka-menu-card{color:#fff;text-shadow:0 1px 2px rgba(0,0,0,.22)}
.ka-menu-card__icon{color:#fff;border:1px solid rgba(255,255,255,.22);box-shadow:inset 0 1px 0 rgba(255,255,255,.12)}
.ka-menu-card strong{color:#fff}
[data-theme="dark"] .ka-menu-card{box-shadow:0 10px 24px rgba(0,0,0,.34),inset 0 1px 0 rgba(255,255,255,.06)}
[data-theme="dark"] .ka-menu-card__icon{background:rgba(255,255,255,.12)}

/* Theme contrast pass — menu cards, profile and home surfaces */
.ka-menu-card,.ka-menu-card strong,.ka-menu-card .ka-menu-card__icon{color:#fff}
.ka-menu-card__count,.ka-menu-card .count,.ka-menu-card [data-count]{color:#fff!important}
.ka-menu-card__icon{background:rgba(255,255,255,.16);border:1px solid rgba(255,255,255,.22)}
.ka-menu-card::after{opacity:.72}
[data-theme="dark"] .ka-menu-card{filter:saturate(.9) brightness(.92)}
[data-theme="dark"] .ka-menu-card strong{color:#fff;text-shadow:0 1px 2px rgba(0,0,0,.28)}
[data-theme="dark"] .ka-menu-card__icon{background:rgba(255,255,255,.13);border-color:rgba(255,255,255,.18)}
.ka-bottom-item.active:not(.ka-bottom-menu) .ka-bottom-icon{background:var(--ka-nav-active-bg);color:var(--ka-nav-active-text)}
.ka-bottom-item.active:not(.ka-bottom-menu){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--ka-primary) 10%,transparent)}
.ka-menu-card{position:relative;overflow:hidden}
.ka-menu-card::before{content:"";position:absolute;inset:auto -14% -38% auto;width:58%;aspect-ratio:1;border-radius:50%;background:rgba(255,255,255,.10);pointer-events:none}
.ka-menu-card>*{position:relative;z-index:1}
[data-theme="dark"] .ka-menu-card--green{background:linear-gradient(145deg,#276e59,#174b3d)}
[data-theme="dark"] .ka-menu-card--amber{background:linear-gradient(145deg,#8b7015,#59490d)}
[data-theme="dark"] .ka-menu-card--cyan{background:linear-gradient(145deg,#2c7180,#1e505c)}
[data-theme="dark"] .ka-menu-card--violet,.ka-menu-card--purple{background:linear-gradient(145deg,#604b86,#40315e)}
[data-theme="dark"] .ka-menu-card--red{background:linear-gradient(145deg,#854843,#5b302d)}
[data-theme="dark"] .ka-menu-card--orange{background:linear-gradient(145deg,#966126,#654117)}
[data-theme="dark"] .ka-menu-card--slate{background:linear-gradient(145deg,#59656e,#3d464d)}

