/* Menü listesi ve başlık satırı */
.ka-menu-head {
  background: var(--ka-header-bg) !important;
  border-bottom-color: var(--ka-border) !important;
  color: var(--ka-text) !important;
}
.ka-menu-head h2 {
  color: var(--ka-text) !important;
}
.ka-menu-head .ka-icon-button {
  color: var(--ka-text) !important;
}
[data-theme="dark"] .ka-menu-head {
  background: #0b0b0b !important;
  border-bottom-color: #252525 !important;
  color: #f5f5f5 !important;
}
[data-theme="dark"] .ka-menu-head h2 {
  color: #f5f5f5 !important;
}
[data-theme="dark"] .ka-menu-head .ka-icon-button {
  color: #f5f5f5 !important;
  background: transparent !important;
}
[data-theme="dark"] .ka-menu-page {
  background: #080808 !important;
  color: #f5f5f5 !important;
}

/* Menü listesi — liste satırları */
[data-theme="dark"] .ka-menu-list > .ka-btn {
  background: #141414 !important;
  color: #f5f5f5 !important;
  border-color: #252525 !important;
}
[data-theme="dark"] .ka-menu-list > .ka-btn .ka-avatar {
  background: #2b2b2b !important;
  color: #ffc400 !important;
}
[data-theme="dark"] .ka-menu-list > .ka-btn strong {
  color: #f5f5f5 !important;
}
[data-theme="dark"] .ka-menu-list > .ka-btn > span:last-child {
  color: #a0a0a0 !important;
}

/* ── PROFİL SAYFASI KARTLARI (Resim 1) ── */
/* İstatistik, eylem ve temel bilgi kartları */
[data-theme="dark"] .ka-profile-page .ka-profile-stat {
  background: #141414 !important;
  border-color: #252525 !important;
  color: #f5f5f5 !important;
}
[data-theme="dark"] .ka-profile-page .ka-profile-stat__icon {
  background: #2b2b2b !important;
  color: #ffc400 !important;
}
[data-theme="dark"] .ka-profile-page .ka-profile-stat > b {
  color: #ffc400 !important;
}
[data-theme="dark"] .ka-profile-page .ka-profile-stat > small {
  color: #a0a0a0 !important;
}
[data-theme="dark"] .ka-profile-page .ka-profile-action {
  background: #141414 !important;
  border-color: #252525 !important;
  color: #f5f5f5 !important;
}
[data-theme="dark"] .ka-profile-page .ka-profile-action__icon {
  background: #2b2b2b !important;
  color: #ffc400 !important;
}
[data-theme="dark"] .ka-profile-page .ka-profile-action__copy strong {
  color: #f5f5f5 !important;
}
[data-theme="dark"] .ka-profile-page .ka-profile-action__copy small {
  color: #a0a0a0 !important;
}
[data-theme="dark"] .ka-profile-page .ka-profile-action__count {
  background: #1f1f1f !important;
}
[data-theme="dark"] .ka-profile-page .ka-profile-action__count b {
  color: var(--ka-module-text) !important;
}
[data-theme="dark"] .ka-profile-page .ka-profile-action__count small {
  color: var(--ka-module-muted) !important;
}
[data-theme="dark"] .ka-profile-page .ka-profile-action__chevron {
  color: var(--ka-module-muted) !important;
}
/* Temel Bilgiler bölümü / ka-card */
[data-theme="dark"] .ka-profile-page .ka-card {
  background: var(--ka-module-surface) !important;
  border-color: #252525 !important;
  color: var(--ka-module-text) !important;
}
[data-theme="dark"] .ka-profile-page .ka-card__header,
[data-theme="dark"] .ka-profile-page .ka-card__body {
  background: var(--ka-module-surface) !important;
  color: var(--ka-module-text) !important;
  border-color: #252525 !important;
}
[data-theme="dark"] .ka-profile-page .ka-card *:not(.ka-profile-action__icon):not(.ka-badge) {
  color: inherit;
}
[data-theme="dark"] .ka-profile-page .ka-profile-section__head > span {
  color: var(--ka-module-accent) !important;
}
[data-theme="dark"] .ka-profile-page .ka-profile-section__head h3 {
  color: var(--ka-module-text) !important;
}
[data-theme="dark"] .ka-profile-page .ka-profile-section__head p {
  color: var(--ka-module-muted) !important;
}

/* ── RAPOR/DÜZENLE/KAPAT TOOLBAR BUTONLARI (Resim 1 üst kısım) ── */
[data-theme="dark"] .dv3h .dv3btn,
[data-theme="dark"] [data-profile-toolbar] .ka-btn,
[data-theme="dark"] .ka-teacher-profile-toolbar .ka-btn {
  background: var(--ka-module-surface-raised) !important;
  border-color: var(--ka-module-border-strong) !important;
  color: var(--ka-module-text) !important;
}

/* ===== TEMA RENK DÜZELTMELERİ v3 — 4 ekran sorunu =====
   Resim 1: Mesajlaşma başlık/metin görünmüyor (koyu üstünde koyu)
   Resim 2: Rapor/Düzenle/Kapat butonları siyah arka plan
   Resim 3: Ana sayfa boş kh-dynamic alanı
   Resim 4: Arama boş-durum kartı beyaz
*/

/* ── RESİM 1: MESAJlaşma sayfası başlık ve metinler ── */
[data-theme="dark"] .ka-communication-page,
[data-theme="dark"] .ka-communication-page h1,
[data-theme="dark"] .ka-communication-page h2,
[data-theme="dark"] .ka-communication-page h3 {
  color: var(--ka-module-text) !important;
}
[data-theme="dark"] .ka-communication-page .ka-communication-heading h2 {
  color: var(--ka-module-text) !important;
}
[data-theme="dark"] .ka-communication-page .ka-communication-heading p,
[data-theme="dark"] .ka-communication-page .ka-muted,
[data-theme="dark"] .ka-communication-page p {
  color: var(--ka-module-muted) !important;
}
[data-theme="dark"] .ka-communication-page .ka-field__label {
  color: var(--ka-module-text) !important;
}
/* Mesaj listesi: konuşma satırları beyaz kalmasın */
[data-theme="dark"] .ka-communication-page .ka-list-card,
[data-theme="dark"] .ka-communication-page .ka-list-card .ka-card__body,
[data-theme="dark"] .ka-communication-page .ka-card,
[data-theme="dark"] .ka-communication-page .ka-card__body {
  background: var(--ka-module-surface) !important;
  border-color: var(--ka-module-border) !important;
  color: var(--ka-module-text) !important;
}
[data-theme="dark"] .ka-communication-page .ka-list-card strong,
[data-theme="dark"] .ka-communication-page .ka-list-card b {
  color: var(--ka-module-text) !important;
}
[data-theme="dark"] .ka-communication-page .ka-list-card small,
[data-theme="dark"] .ka-communication-page .ka-list-card .ka-muted {
  color: var(--ka-module-muted) !important;
}
/* Konuşma avatarı */
[data-theme="dark"] .ka-communication-page .ka-avatar,
[data-theme="dark"] .ka-communication-page .ka-list-card .ka-avatar {
  background: var(--ka-module-icon-surface) !important;
  color: var(--ka-module-accent) !important;
}
/* "Mesajlar" başlığı altındaki section başlıkları */
[data-theme="dark"] .ka-communication-page > .ka-stack > strong,
[data-theme="dark"] .ka-communication-page [data-communication-section] strong,
[data-theme="dark"] .ka-communication-page h3 {
  color: var(--ka-module-text) !important;
}
/* Arama kutusu */
[data-theme="dark"] .ka-communication-page .ka-communication-search input,
[data-theme="dark"] .ka-communication-page input[type="search"] {
  background: var(--ka-module-surface-raised) !important;
  border-color: var(--ka-module-border-strong) !important;
  color: var(--ka-module-text) !important;
}
[data-theme="dark"] .ka-communication-page input::placeholder {
  color: var(--ka-module-muted) !important;
}
/* Rozet sayaç */
[data-theme="dark"] .ka-communication-page .ka-badge {
  background: var(--ka-module-icon-surface) !important;
  color: var(--ka-module-muted) !important;
}

/* ── RESİM 2: Öğretmen profil araç çubuğu — Rapor/Düzenle/Kapat ── */
/* Bu butonlar dv3 (belge görüntüleyici) değil, profil toolbar'ı */
[data-theme="dark"] .ka-teacher-profile-toolbar .ka-btn,
[data-theme="dark"] .ka-teacher-profile-toolbar .ka-btn--secondary {
  background: var(--ka-module-surface-raised) !important;
  border-color: var(--ka-module-border-strong) !important;
  color: var(--ka-module-text) !important;
  box-shadow: 0 2px 8px rgba(0,0,0,.4) !important;
}
[data-theme="dark"] .ka-teacher-profile-toolbar .ka-btn svg,
[data-theme="dark"] .ka-teacher-profile-toolbar .ka-btn span {
  color: var(--ka-module-text) !important;
}
/* Profil araç çubuğu genel wrapper */
[data-theme="dark"] [data-ka-profile-toolbar],
[data-theme="dark"] [data-profile-actions] {
  background: transparent !important;
}
/* Temel bilgiler kartı içindeki "Ara" butonu */
[data-theme="dark"] .ka-teacher-detail-section .ka-btn--secondary,
[data-theme="dark"] .ka-teacher-detail-section .ka-btn {
  background: var(--ka-module-surface-raised) !important;
  border-color: var(--ka-module-border-strong) !important;
  color: var(--ka-module-text) !important;
}
/* Temel Bilgiler bölüm başlığı */
[data-theme="dark"] .ka-teacher-detail-section > .ka-card__header {
  background: var(--ka-module-surface-raised) !important;
  border-color: var(--ka-module-border) !important;
}
[data-theme="dark"] .ka-teacher-detail-section > .ka-card__header h3,
[data-theme="dark"] .ka-teacher-detail-section > .ka-card__header * {
  color: var(--ka-module-text) !important;
}
/* Profil stat kartları (WhatsApp / Ara / Mesaj / Program) */
[data-theme="dark"] .ka-teacher-contact-grid > a,
[data-theme="dark"] .ka-teacher-contact-grid > button {
  background: var(--ka-module-surface-raised) !important;
  border-color: var(--ka-module-border) !important;
  color: var(--ka-module-text) !important;
}
[data-theme="dark"] .ka-teacher-contact-grid b {
  color: var(--ka-module-text) !important;
}
[data-theme="dark"] .ka-teacher-contact-grid > a > span,
[data-theme="dark"] .ka-teacher-contact-grid > button > span {
  background: var(--ka-module-icon-surface) !important;
  color: var(--ka-module-accent) !important;
}
/* HAFTALIK DERS / BUGÜN / NÖBET / SORUMLULUK kartları */
[data-theme="dark"] .ka-teacher-stat-grid > .ka-card {
  background: var(--ka-module-surface) !important;
  border-color: var(--ka-module-border) !important;
  color: var(--ka-module-text) !important;
}
[data-theme="dark"] .ka-teacher-stat-grid small {
  color: var(--ka-module-muted) !important;
}
[data-theme="dark"] .ka-teacher-stat-grid b {
  color: var(--ka-module-accent) !important;
}
[data-theme="dark"] .ka-teacher-stat-grid span {
  color: var(--ka-module-text) !important;
}
/* Temel bilgiler satır içi (Telefon, vb.) */
[data-theme="dark"] .ka-teacher-detail-row {
  border-bottom-color: var(--ka-module-border) !important;
}
[data-theme="dark"] .ka-teacher-detail-row b {
  color: var(--ka-module-text) !important;
}
[data-theme="dark"] .ka-teacher-detail-row span {
  color: var(--ka-module-muted) !important;
}

/* ── RESİM 3: Ana sayfa kh-dynamic boş/görünmez alan ── */
/* Tarama barcode alanı veya boş dyn-item */
html[data-theme="dark"] .ka-home .kh-dynamic:not(:empty) {
  background: transparent !important;
}
html[data-theme="dark"] .ka-home .kh-dyn-item {
  background: var(--ka-module-surface) !important;
  border-color: var(--ka-module-border) !important;
  color: var(--ka-module-text) !important;
}
html[data-theme="dark"] .ka-home .kh-dyn-icon {
  background: var(--ka-module-icon-surface) !important;
  color: var(--ka-module-accent) !important;
}
/* Barkod/QR tarayıcı alanı */
html[data-theme="dark"] .ka-home [data-home-section="scan"],
html[data-theme="dark"] .ka-home .kh-scan-area,
html[data-theme="dark"] .ka-home .kh-qr-area {
  background: var(--ka-module-surface) !important;
  border-color: var(--ka-module-border) !important;
  color: var(--ka-module-text) !important;
}
/* Genel: görünmez kalan her bölüm başlığını zorla */
html[data-theme="dark"] .ka-home .kh-section > .kh-section-head,
html[data-theme="dark"] .ka-home .kh-section > .kh-section-head * {
  color: var(--ka-module-text) !important;
}
html[data-theme="dark"] .ka-home .kh-section > .kh-section-head svg {
  color: var(--ka-module-accent) !important;
  stroke: var(--ka-module-accent) !important;
}

/* ── RESİM 4: Arama boş-durum ve arama kutusu ── */
/* "Aramaya başlayın" kartı beyaz kalıyor */
[data-theme="dark"] .ka-search-empty {
  background: var(--ka-module-surface) !important;
  border-color: var(--ka-module-border) !important;
  color: var(--ka-module-muted) !important;
}
[data-theme="dark"] .ka-search-empty > strong {
  color: var(--ka-module-text) !important;
}
[data-theme="dark"] .ka-search-empty > small {
  color: var(--ka-module-muted) !important;
}
[data-theme="dark"] .ka-search-empty > span {
  background: var(--ka-module-icon-surface) !important;
  color: var(--ka-module-accent) !important;
}
/* "Arama Sonuçları" başlık ve alt metin */
[data-theme="dark"] .ka-search-results-head strong {
  color: var(--ka-module-text) !important;
}
[data-theme="dark"] .ka-search-results-head small {
  color: var(--ka-module-muted) !important;
}
/* Hero kart: "HIZLI ERİŞİM / Arama" */
[data-theme="dark"] .ka-search-hero {
  background: var(--ka-module-surface) !important;
  border-color: var(--ka-module-border) !important;
}
[data-theme="dark"] .ka-search-hero .ka-search-hero__copy > span {
  color: var(--ka-module-accent) !important;
}
[data-theme="dark"] .ka-search-hero h2 {
  color: var(--ka-module-text) !important;
}
[data-theme="dark"] .ka-search-hero p {
  color: var(--ka-module-muted) !important;
}
[data-theme="dark"] .ka-search-hero .ka-search-hero__icon {
  background: var(--ka-module-icon-surface) !important;
  color: var(--ka-module-accent) !important;
}
/* Arama kutusu */
[data-theme="dark"] .ka-search-box {
  background: var(--ka-module-surface-raised) !important;
  border-color: var(--ka-module-border-strong) !important;
}
[data-theme="dark"] .ka-search-box input {
  color: var(--ka-module-text) !important;
  caret-color: var(--ka-module-accent) !important;
}
[data-theme="dark"] .ka-search-box input::placeholder {
  color: var(--ka-module-muted) !important;
}
/* Gelişmiş Filtreler kartı */
[data-theme="dark"] .ka-search-filters {
  background: var(--ka-module-surface) !important;
  border-color: var(--ka-module-border) !important;
}
[data-theme="dark"] .ka-search-filters__copy strong {
  color: var(--ka-module-text) !important;
}
[data-theme="dark"] .ka-search-filters__copy small {
  color: var(--ka-module-muted) !important;
}
[data-theme="dark"] .ka-search-filters__icon {
  background: var(--ka-module-icon-surface) !important;
}
[data-theme="dark"] .ka-search-filters__status > b {
  background: var(--ka-module-surface-muted) !important;
  color: var(--ka-module-muted) !important;
}
/* Kategori pill butonları (Tümü, Öğretmen...) */
[data-theme="dark"] .ka-search-category {
  background: var(--ka-module-surface-raised) !important;
  border-color: var(--ka-module-border-strong) !important;
  color: var(--ka-module-muted) !important;
}
[data-theme="dark"] .ka-search-category.active,
[data-theme="dark"] .ka-search-category[aria-pressed="true"] {
  background: var(--ka-module-accent) !important;
  border-color: var(--ka-module-accent) !important;
  color: var(--ka-button-text) !important;
}


/* ===== DARK THEME VISIBLE-SURFACE RESET v975 =====
   Bu katman, eski modül CSS'lerinin tema değişkenlerini ezdiği ekranları
   tekrar merkezi koyu yüzeye bağlar. Semantik başarı/uyarı renkleri korunur. */
[data-theme="dark"] .ka-home,
[data-theme="dark"] .ka-home-section,
[data-theme="dark"] .ka-home-section__body,
[data-theme="dark"] .ka-school-summary-section,
[data-theme="dark"] .ka-school-summary-grid{
  background:var(--ka-app-bg)!important;
  color:var(--ka-module-text)!important;
}
[data-theme="dark"] .ka-school-summary-card{
  background:var(--ka-module-surface)!important;
  color:var(--ka-module-text)!important;
  border-color:var(--ka-module-border-strong)!important;
  box-shadow:0 6px 18px rgba(0,0,0,.28)!important;
}
[data-theme="dark"] .ka-school-summary-card *,
[data-theme="dark"] .ka-school-summary-card>b,
[data-theme="dark"] .ka-school-summary-card>small{
  color:var(--ka-module-text)!important;
}
[data-theme="dark"] .ka-school-summary-card .ka-school-summary-meta,
[data-theme="dark"] .ka-school-summary-card .ka-school-summary-meta *{
  color:var(--ka-module-muted)!important;
}
[data-theme="dark"] .ka-school-summary-icon,
[data-theme="dark"] .ka-school-stage-icon{
  background:var(--ka-module-icon-surface)!important;
  color:var(--ka-module-accent)!important;
  box-shadow:inset 0 0 0 1px var(--ka-module-border-strong)!important;
}
[data-theme="dark"] .ka-school-summary-card::after{
  background:rgba(255,196,0,.08)!important;
}

/* Ana sayfa eski/nested kartlar: beyaz yüzey sızıntısını kapat. */
[data-theme="dark"] .ka-home [class*="kh-"],
[data-theme="dark"] .ka-home [class*="home-section"]{
  border-color:var(--ka-module-border);
}
[data-theme="dark"] .ka-home .kh-card,
[data-theme="dark"] .ka-home .kh-food-card,
[data-theme="dark"] .ka-home .kh-weekday,
[data-theme="dark"] .ka-home .kh-notes,
[data-theme="dark"] .ka-home .kh-news,
[data-theme="dark"] .ka-home .kh-dyn-item{
  background:var(--ka-module-surface)!important;
  color:var(--ka-module-text)!important;
}
[data-theme="dark"] .ka-home .kh-card h1,
[data-theme="dark"] .ka-home .kh-card h2,
[data-theme="dark"] .ka-home .kh-card h3,
[data-theme="dark"] .ka-home .kh-card strong,
[data-theme="dark"] .ka-home .kh-card b{
  color:var(--ka-module-text)!important;
}
[data-theme="dark"] .ka-home .kh-card small,
[data-theme="dark"] .ka-home .kh-card .ka-muted{
  color:var(--ka-module-muted)!important;
}

/* Menü liste ekranı: başlık, liste ve satırları tek dark sistemde tut. */
[data-theme="dark"] #kaMenuLayer,
[data-theme="dark"] #kaMenuLayer .ka-menu-page,
[data-theme="dark"] #kaMenuLayer .ka-menu-head,
[data-theme="dark"] #kaMenuLayer .ka-menu-list{
  background:var(--ka-app-bg)!important;
  color:var(--ka-module-text)!important;
}
[data-theme="dark"] #kaMenuLayer .ka-menu-head{
  border-bottom-color:var(--ka-module-border)!important;
}
[data-theme="dark"] #kaMenuLayer .ka-menu-head h2,
[data-theme="dark"] #kaMenuLayer .ka-menu-head h2 *,
[data-theme="dark"] #kaMenuLayer .ka-menu-head .ka-icon-button{
  color:var(--ka-module-text)!important;
  opacity:1!important;
}
[data-theme="dark"] #kaMenuLayer .ka-menu-list>.ka-btn,
[data-theme="dark"] #kaMenuLayer .ka-menu-list>.ka-btn.ka-btn--secondary{
  background:var(--ka-module-surface)!important;
  color:var(--ka-module-text)!important;
  border-color:var(--ka-module-border)!important;
}
[data-theme="dark"] #kaMenuLayer .ka-menu-list>.ka-btn strong,
[data-theme="dark"] #kaMenuLayer .ka-menu-list>.ka-btn span{
  color:var(--ka-module-text)!important;
}
[data-theme="dark"] #kaMenuLayer .ka-menu-list>.ka-btn .ka-avatar{
  background:var(--ka-module-icon-surface)!important;
  border-color:var(--ka-module-border-strong)!important;
}

/* Profil ekranı: gerçek kartların sınıfı değişse bile beyaz kart kalmasın. */
[data-theme="dark"] .ka-profile-page>section:not(.ka-profile-hero),
[data-theme="dark"] .ka-profile-page>article,
[data-theme="dark"] .ka-profile-page .ka-profile-stats,
[data-theme="dark"] .ka-profile-page .ka-profile-stat,
[data-theme="dark"] .ka-profile-page .ka-profile-actions,
[data-theme="dark"] .ka-profile-page .ka-profile-action,
[data-theme="dark"] .ka-profile-page .ka-card,
[data-theme="dark"] .ka-profile-page .ka-card__body{
  background:var(--ka-module-surface)!important;
  color:var(--ka-module-text)!important;
  border-color:var(--ka-module-border)!important;
}
[data-theme="dark"] .ka-profile-page>section:not(.ka-profile-hero) h1,
[data-theme="dark"] .ka-profile-page>section:not(.ka-profile-hero) h2,
[data-theme="dark"] .ka-profile-page>section:not(.ka-profile-hero) h3,
[data-theme="dark"] .ka-profile-page>section:not(.ka-profile-hero) strong,
[data-theme="dark"] .ka-profile-page>section:not(.ka-profile-hero) b,
[data-theme="dark"] .ka-profile-page>article h1,
[data-theme="dark"] .ka-profile-page>article h2,
[data-theme="dark"] .ka-profile-page>article h3,
[data-theme="dark"] .ka-profile-page>article strong,
[data-theme="dark"] .ka-profile-page>article b{
  color:var(--ka-module-text)!important;
}
[data-theme="dark"] .ka-profile-page>section:not(.ka-profile-hero) small,
[data-theme="dark"] .ka-profile-page>section:not(.ka-profile-hero) p,
[data-theme="dark"] .ka-profile-page>article small,
[data-theme="dark"] .ka-profile-page>article p{
  color:var(--ka-module-muted)!important;
}

