/* ===== MENÜ — 2x5 KOMPAKT GRID / MERKEZİ İKON v1055 =====
   Mobil menüde tüm kategori kartları tek ekranda 2 sütun x 5 satır
   görünür. İkonlar ve başlıklar kartın yatay merkezine hizalanır. */
#kaMenuLayer .ka-menu-grid{
  grid-template-columns:repeat(2,minmax(0,1fr))!important;
  grid-auto-rows:112px!important;
  row-gap:8px!important;
  column-gap:8px!important;
  padding:10px max(10px,var(--ka-safe-right)) calc(12px + var(--ka-safe-bottom)) max(10px,var(--ka-safe-left))!important;
  align-content:start!important;
}
#kaMenuLayer .ka-menu-card{
  width:100%!important;
  height:112px!important;
  min-height:112px!important;
  aspect-ratio:auto!important;
  padding:9px 10px!important;
  gap:6px!important;
  align-items:center!important;
  justify-content:center!important;
  text-align:center!important;
  border-radius:18px!important;
}
#kaMenuLayer .ka-menu-card__icon{
  width:42px!important;
  height:42px!important;
  flex:0 0 42px!important;
  margin:0!important;
  border-radius:13px!important;
  font-size:22px!important;
  display:grid!important;
  place-items:center!important;
}
#kaMenuLayer .ka-menu-card strong{
  margin:0!important;
  padding:0 18px!important;
  width:100%!important;
  text-align:center!important;
  font-size:12.2px!important;
  line-height:1.15!important;
}
#kaMenuLayer .ka-menu-card>.ka-badge{
  right:8px!important;
  top:8px!important;
  min-width:24px!important;
  height:24px!important;
  font-size:10px!important;
}
@media(max-width:380px){
  #kaMenuLayer .ka-menu-grid{
    grid-auto-rows:104px!important;
    row-gap:7px!important;
    column-gap:7px!important;
    padding-inline:max(8px,var(--ka-safe-left))!important;
  }
  #kaMenuLayer .ka-menu-card{
    height:104px!important;
    min-height:104px!important;
    padding:7px 8px!important;
  }
  #kaMenuLayer .ka-menu-card__icon{
    width:38px!important;
    height:38px!important;
    flex-basis:38px!important;
    font-size:20px!important;
  }
  #kaMenuLayer .ka-menu-card strong{
    font-size:11.5px!important;
    padding-inline:12px!important;
  }
}


